import{B as e,F as t,Ft as n,H as r,M as i,V as a,W as o,cn as s,gr as c,kt as l,x as u}from"./BremBuoM.js";import{f as d,t as f}from"./BR5fhm-r.js";import{n as p,t as m}from"./Cayzuce-.js";var h={class:`docs-layout`},g={class:`panel docs-nav`},_={class:`panel-body nav-list`},v=[`href`],y=o({__name:`docs`,setup(o){m({title:`方案文档`});let y=[{id:`summary`,label:`架构总览`},{id:`model`,label:`核心对象`},{id:`flow`,label:`授权计算`},{id:`assignment`,label:`组织任职`},{id:`data`,label:`数据权限`},{id:`backend`,label:`前后端执行`},{id:`fields`,label:`关键字段`},{id:`boundary`,label:`本期边界`}];return(o,m)=>{let b=f,x=p,S=d;return l(),t(`div`,null,[r(x,{title:`实现随方案一起交付`,description:`本页内嵌评审后的统一口径：功能改名为资源，删除旧业务资源层，组织岗位独立维护用户任职。`},{default:s(()=>[r(b,{to:`/simulator`,color:`primary`,icon:`i-lucide-flask-conical`,label:`打开模拟器`})]),_:1}),i(`div`,h,[i(`aside`,g,[m[0]||=i(`div`,{class:`panel-head`},[i(`div`,null,[i(`h3`,null,`本页目录`)])],-1),i(`div`,_,[(l(),t(u,null,n(y,e=>i(`a`,{key:e.id,href:`#${e.id}`,class:`nav-link`,style:{color:`#526178`}},[r(S,{name:`i-lucide-hash`,size:`13`}),a(c(e.label),1)],8,v)),64))])]),m[1]||=e(`<article class="panel docs-content"><h2 id="summary">架构总览</h2><p>系统采用 <b>RBAC 角色模板 + 用户直接加授 + 菜单资源包 + 组织/岗位数据范围</b>。运营侧只有“菜单”和“资源”两类可授权对象；资源就是原“功能”，代表一个原子业务动作，例如“创建采购单” / <code>sc.purchase_order.create</code>。</p><pre>有效资源(u) = 角色资源(u) ∪ 用户直授资源(u) ∪ 菜单 CORE 资源(u)
允许(u, 资源码, 数据对象)
  = 已认证
  AND 资源码 ∈ 有效资源(u)
  AND 数据对象 ∈ 岗位在对应数据域的正式范围</pre><h2 id="model">核心对象</h2><table><thead><tr><th>对象</th><th>职责</th><th>是否直接授权</th></tr></thead><tbody><tr><td>用户</td><td>登录主体；基础账号与组织任职分开维护</td><td>授权主体</td></tr><tr><td>角色</td><td>复用常规菜单和资源的模板</td><td>授给用户</td></tr><tr><td>资源</td><td>唯一能力合同，如 <code>sc.purchase_order.create</code></td><td>是</td></tr><tr><td>菜单</td><td>板块 → 目录 → 页面菜单；页面叶子携带资源包</td><td>仅页面菜单</td></tr><tr><td>组织 / 岗位</td><td>维护用户正式任职，并提供按数据域的数据范围</td><td>否</td></tr></tbody></table><p><b>已删除旧资源层：</b>不再登记 REPORT / TEMPLATE 业务资源，也不维护资源到功能的映射。API、任务和服务方法只是执行点，直接校验资源码。</p><h2 id="flow">授权计算</h2><h3>菜单资源包</h3><p>CORE 是进入页面所需的最小资源集合，随页面菜单自动展开；OPTIONAL 包含新建、编辑、导出、删除、审批等资源，由管理员单独选择。高风险资源不能成为 CORE。</p><h3>父节点语义</h3><p>板块或目录勾选只保存当前页面菜单叶子集合。未来新增子菜单不会静默进入历史授权。</p><h3>来源去重</h3><p>同一资源可同时来自角色、用户直授和菜单 CORE。撤销某一来源时，如果仍有其他来源，资源继续有效。</p><h2 id="assignment">组织任职</h2><ol><li>用户页只创建姓名、账号、工号和状态，不选择组织、岗位或初始角色。</li><li>组织管理员进入“组织与岗位”，选择组织和岗位，再通过用户下拉框指定任职。</li><li>调岗时在同一入口重新选择组织与岗位，系统覆盖主任职、提升策略版本并写入审计。</li><li>用户授权抽屉不展示或修改数据范围；本期不提供用户临时数据范围。</li></ol><h2 id="data">数据权限</h2><p>正式数据范围按“岗位 × 数据域”配置，而不是挂在用户或业务角色上。第一版范围固定为 NONE、SELF、DEPT、DEPT_AND_DESCENDANTS、CUSTOM_DEPTS、ALL。未配置按 NONE。</p><pre>资源 sc.purchase_order.approve 已授权
AND 采购主管 @ 供应链部
    sc.purchase_order → DEPT_AND_DESCENDANTS
= 可审批本部门及下级的采购单</pre><h2 id="backend">前后端执行</h2><p>前端路由、按钮与后端控制器 / 服务方法使用同一个资源码。前端隐藏只改善体验；后端逐请求强制校验，并在列表、详情、更新、删除、导出和批量操作上复用同一数据谓词。</p><pre>// 前端：体验控制
const canCreate = hasResource(&#39;sc.purchase_order.create&#39;)

// 后端：安全边界
requireResource(event, &#39;sc.purchase_order.create&#39;)
const scope = resolveDataAccess(userId, &#39;sc.purchase_order&#39;)</pre><p>新增 API 无需创建 API 资源或额外映射功能；执行点必须直接声明一个已启用资源码。未声明、资源不存在或已停用均默认拒绝。</p><h2 id="fields">关键字段</h2><table><thead><tr><th>对象</th><th>本期保留字段</th></tr></thead><tbody><tr><td>用户</td><td>姓名、登录账号、工号、状态</td></tr><tr><td>角色</td><td>名称、编码、业务板块、状态</td></tr><tr><td>资源</td><td>名称、稳定资源码、业务板块、风险等级、数据域、状态</td></tr><tr><td>菜单</td><td>类型、名称、编码、上级、菜单权限码、前端路由</td></tr><tr><td>组织</td><td>名称、上级、类型、负责人</td></tr><tr><td>岗位</td><td>名称、所属组织、按数据域的正式范围</td></tr></tbody></table><h2 id="boundary">本期边界</h2><p>明确不引入多租户、tenant_id、角色层级、用户级 DENY、用户临时数据范围、API 资源层、报表 / 模板资源目录、对象实例 ACL、任意 SQL / 表达式型 ABAC、字段级授权或独立策略引擎。静态 Demo 的浏览器 Mock 身份仅用于演示，生产环境应接入企业 SSO / Session。</p></article>`,1)])])}}});export{y as default};